const _mcAl = x => String(x).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
const _mcCache = new Map();
// class code of a model-table row (brand, model) -- 'U' when unclassified
function modelClassOf(brand, model){
  const ck = brand + '|' + model;
  let c = _mcCache.get(ck);
  if(c === undefined){
    const bk = _mcAl(MODEL_CLASS_ALIASES[brand] || brand);
    let m = _mcAl(String(model).replace(/\s+(BEV|PHEV|HEV|ICE)$/i, ''));
    if(m.startsWith(bk) && m.length > bk.length) m = m.slice(bk.length);
    c = MODEL_CLASS[bk + '|' + m] || 'U'; _mcCache.set(ck, c);
  }
  return c;
}
